-- MP-0002: guarded editorial content import. Deploy portraits before applying.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='bersatu' and type='party') then raise exception 'MP-0002: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='pas' and type='party') then raise exception 'MP-0002: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('shahidan-kassim','mohd-suhaimi-abdullah','abdul-ghani-ahmad') and (type <> 'politician' or owner_id is not null)) then raise exception 'MP-0002: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('arau','langkawi','jerlun') and slug not in ('shahidan-kassim','mohd-suhaimi-abdullah','abdul-ghani-ahmad')) then raise exception 'MP-0002: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'MP-0002:%' and (m.source_type <> 'editorial' or e.slug not in ('shahidan-kassim','mohd-suhaimi-abdullah','abdul-ghani-ahmad') or m.import_key not like 'MP-0002:' || e.slug || ':%')) then raise exception 'MP-0002: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'shahidan-kassim','Shahidan Kassim','opposition','Member of the Dewan Rakyat','Arau','Perlis','Shahidan Kassim represents Arau, Perlis, in the Dewan Rakyat. A PAS member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4042','/portraits/shahidan-kassim.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P003.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4042"}, {"label": "PAS · current parliamentary representatives", "url": "https://pas.org.my/ahli-parlimen-pas-pru-ke-15/"}]'::jsonb from public.entities parent where parent.slug='pas' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

