ded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('shahidan-kassim','mohd-suhaimi-abdullah','abdul-ghani-ahmad') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0002: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0002:abdul-ghani-ahmad:annual-orphan-support','Continue annual Ramadan and Aidilfitri support for orphans in Jerlun','Social welfare',null,null,null,'2025-03-17','https://harakahdaily.net/2025/03/17/pas-jerlun-rai-anak-anak-yatim-setiap-tahun/','2025-03-17','https://harakahdaily.net/2025/03/17/pas-jerlun-rai-anak-anak-yatim-setiap-tahun/','Abdul Ghani committed his local organisation to continue the annual support programme.','The report describes 31 children attending the preceding day’s programme. That event does not verify delivery of every later annual round. Current overall outcome and completion remain unknown.','2026-11-09','editorial',false from public.entities e where e.slug='abdul-ghani-ahmad' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

